package com.nedjma.app;
import android.app.Activity; import android.os.Bundle; import android.graphics.Color; import android.net.Uri; import android.content.Intent; import android.webkit.*; import android.view.Window; import android.view.WindowManager;
public class MainActivity extends Activity {
 private WebView webView; private ValueCallback<Uri[]> uploadCallback; private static final int FILE_CHOOSER_REQUEST=4201;
 @Override public void onCreate(Bundle state){super.onCreate(state); Window w=getWindow(); w.setStatusBarColor(Color.rgb(10,10,10)); w.setNavigationBarColor(Color.rgb(10,10,10)); getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); webView=new WebView(this); webView.setBackgroundColor(Color.rgb(10,10,10)); WebSettings s=webView.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setDatabaseEnabled(true); s.setAllowFileAccess(true); s.setAllowContentAccess(true); s.setJavaScriptCanOpenWindowsAutomatically(false); s.setSupportMultipleWindows(false); s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW); webView.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v, WebResourceRequest r){Uri u=r.getUrl(); String scheme=u.getScheme()==null?"":u.getScheme(),host=u.getHost()==null?"":u.getHost(); if("https".equalsIgnoreCase(scheme)&&(host.equals("jyyslgvlnjhuvnnzcmbf.supabase.co")||host.equals("cdn.jsdelivr.net")))return false; if("file".equalsIgnoreCase(scheme)&&u.getPath()!=null&&u.getPath().startsWith("/android_asset/"))return false; if("https".equalsIgnoreCase(scheme)){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){} return true;} return true;}}); webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(uploadCallback!=null)uploadCallback.onReceiveValue(null); uploadCallback=cb; try{startActivityForResult(p.createIntent(),FILE_CHOOSER_REQUEST);}catch(Exception e){uploadCallback=null;cb.onReceiveValue(null);return false;} return true;}}); setContentView(webView); if(state==null)webView.loadUrl("file:///android_asset/index.html");else webView.restoreState(state);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE_CHOOSER_REQUEST&&uploadCallback!=null){uploadCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));uploadCallback=null;}}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(webView!=null)webView.saveState(b);}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(uploadCallback!=null){uploadCallback.onReceiveValue(null);uploadCallback=null;}if(webView!=null){webView.destroy();webView=null;}super.onDestroy();}
}
